/* ---- decode state ------------------------------------------------------- */

typedef struct
{
  bool mode64;

  const uint8_t * p;      /* cursor */
  const uint8_t * start;

  bool opsize;            /* 0x66 */
  bool addrsize;          /* 0x67 */
  bool has_rex;
  uint8_t rex;            /* full REX byte (0x40-0x4F) */
  uint8_t seg;            /* segment override prefix byte, 0 if none */
  bool repne;             /* F2 */
  bool rep;               /* F3 */
} DecState;

static hx_x86_reg
gpr64 (int idx)
{
  static const hx_x86_reg map[16] = {
    HX_REG_RAX, HX_REG_RCX, HX_REG_RDX, HX_REG_RBX,
    HX_REG_RSP, HX_REG_RBP, HX_REG_RSI, HX_REG_RDI,
    HX_REG_R8, HX_REG_R9, HX_REG_R10, HX_REG_R11,
    HX_REG_R12, HX_REG_R13, HX_REG_R14, HX_REG_R15
  };
  return map[idx & 15];
}

static int
imm_z_size (DecState * st)
{
  return st->opsize ? 2 : 4;
}

/* Decode ModRM + SIB + displacement; advance cursor past them. Fills the
 * hx_x86 detail (modrm byte, offsets, disp, first memory/reg operand). */
static void
decode_modrm (DecState * st,
              hx_insn * insn,
              hx_x86 * x86,
              const uint8_t * insn_start)
{
  uint8_t modrm = *st->p;
  int mod = modrm >> 6;
  int rm = modrm & 7;
  int reg = (modrm >> 3) & 7;
  int disp_size = 0;
  bool addr16 = !st->mode64 && st->addrsize;
  bool has_sib = false;
  uint8_t sib = 0;

  x86->modrm = modrm;
  x86->encoding.modrm_offset = (uint8_t) (st->p - insn_start);
  st->p++;

  if (mod == 3)
  {
    /* register operand */
    x86->operands[0].type = HX_OP_REG;
    x86->operands[0].reg = gpr64 (rm + ((st->rex & 0x1) ? 8 : 0));
    x86->op_count = 1;
    (void) reg;
    return;
  }

  /* memory operand */
  if (!addr16 && rm == 4)
  {
    has_sib = true;
    sib = *st->p;
    x86->sib = sib;
    st->p++;
  }

  if (addr16)
  {
    if (mod == 0 && rm == 6)
      disp_size = 2;
    else if (mod == 1)
      disp_size = 1;
    else if (mod == 2)
      disp_size = 2;
  }
  else if (mod == 0)
  {
    if (rm == 5)
    {
      disp_size = 4;   /* disp32; RIP-relative in 64-bit */
    }
    else if (has_sib && (sib & 7) == 5)
    {
      disp_size = 4;
    }
  }
  else if (mod == 1)
  {
    disp_size = 1;
  }
  else /* mod == 2 */
  {
    disp_size = 4;
  }

  /* first operand = memory */
  {
    hx_x86_op * op = &x86->operands[0];
    op->type = HX_OP_MEM;
    op->mem.segment = HX_REG_INVALID;
    op->mem.scale = 1;
    op->mem.index = HX_REG_INVALID;
    op->mem.base = HX_REG_INVALID;
    op->mem.disp = 0;

    if (addr16)
    {
      static const hx_x86_reg base[8] = {
        HX_REG_RBX, HX_REG_RBX, HX_REG_RBP, HX_REG_RBP,
        HX_REG_RSI, HX_REG_RDI, HX_REG_RBP, HX_REG_RBX
      };
      static const hx_x86_reg index[8] = {
        HX_REG_RSI, HX_REG_RDI, HX_REG_RSI, HX_REG_RDI,
        HX_REG_INVALID, HX_REG_INVALID, HX_REG_INVALID, HX_REG_INVALID
      };

      if (!(mod == 0 && rm == 6))
      {
        op->mem.base = base[rm];
        op->mem.index = index[rm];
      }
    }
    else if (mod == 0 && rm == 5)
    {
      if (st->mode64)
        op->mem.base = st->addrsize ? HX_REG_EIP : HX_REG_RIP;
    }
    else if (has_sib)
    {
      int base = sib & 7;
      int index = (sib >> 3) & 7;
      int scale = 1 << ((sib >> 6) & 3);
      if (!(mod == 0 && base == 5))
        op->mem.base = gpr64 (base + ((st->rex & 0x1) ? 8 : 0));
      if (index != 4)
      {
        op->mem.index = gpr64 (index + ((st->rex & 0x2) ? 8 : 0));
        op->mem.scale = scale;
      }
    }
    else
    {
      op->mem.base = gpr64 (rm + ((st->rex & 0x1) ? 8 : 0));
    }
    x86->op_count = 1;
  }

  if (disp_size != 0)
  {
    int64_t disp = 0;
    x86->encoding.disp_offset = (uint8_t) (st->p - insn_start);
    x86->encoding.disp_size = (uint8_t) disp_size;
    if (disp_size == 1)
      disp = (int8_t) st->p[0];
    else if (disp_size == 2)
    {
      uint16_t raw_disp = (uint16_t) st->p[0] |
          ((uint16_t) st->p[1] << 8);
      disp = (addr16 && mod == 0 && rm == 6)
          ? (int64_t) raw_disp
          : (int64_t) (int16_t) raw_disp;
    }
    else
      disp = (int32_t) ((uint32_t) st->p[0] | ((uint32_t) st->p[1] << 8) |
          ((uint32_t) st->p[2] << 16) | ((uint32_t) st->p[3] << 24));
    x86->disp = disp;
    x86->operands[0].mem.disp = disp;
    st->p += disp_size;
  }

  (void) insn;
}

/* Consume the immediate of the given byte count. */
static void
skip_imm (DecState * st, int n)
{
  st->p += n;
}

/* ---- control-flow classification ---------------------------------------- */

static const hx_x86_insn jcc_map[16] = {
  HX_INS_JO, HX_INS_JNO, HX_INS_JB, HX_INS_JAE,
  HX_INS_JE, HX_INS_JNE, HX_INS_JBE, HX_INS_JA,
  HX_INS_JS, HX_INS_JNS, HX_INS_JP, HX_INS_JNP,
  HX_INS_JL, HX_INS_JGE, HX_INS_JLE, HX_INS_JG
};

static void
set_imm_target (hx_x86 * x86, int64_t target)
{
  x86->operands[0].type = HX_OP_IMM;
  x86->operands[0].imm = target;
  x86->op_count = 1;
}

static const hx_x86_insn alu_group[8] = {
  HX_INS_ADD, HX_INS_OR, HX_INS_ADC, HX_INS_SBB,
  HX_INS_AND, HX_INS_SUB, HX_INS_XOR, HX_INS_CMP
};

/* Classify common one-byte data-processing opcodes (best-effort; anything not
 * recognised stays HX_INS_OTHER). */
static hx_x86_insn
classify_dp_1byte (uint8_t p, uint8_t modrm, bool mode64)
{
  if (p < 0x40 && (p & 7) <= 5)
    return alu_group[(p >> 3) & 7];      /* ADD..CMP r/imm forms */
  if (p >= 0x88 && p <= 0x8B)
    return HX_INS_MOV;
  if (p == 0x8C || p == 0x8E)
    return HX_INS_MOV;
  if (p == 0x8D)
    return HX_INS_LEA;
  if (p >= 0xB0 && p <= 0xBF)
    return HX_INS_MOV;
  if (p == 0xC6 || p == 0xC7)
    return HX_INS_MOV;
  if (p >= 0xA0 && p <= 0xA3)
    return HX_INS_MOV;
  if (p == 0x84 || p == 0x85 || p == 0xA8 || p == 0xA9)
    return HX_INS_TEST;
  if (p >= 0x58 && p <= 0x5F)
    return HX_INS_POP;
  if (p == 0x80 || p == 0x81 || p == 0x82 || p == 0x83)
    return alu_group[(modrm >> 3) & 7];  /* group 1 */
  if (p == 0xFE)
    return (((modrm >> 3) & 7) == 0) ? HX_INS_INC : HX_INS_DEC;
  if (!mode64 && p >= 0x40 && p <= 0x47)
    return HX_INS_INC;
  if (!mode64 && p >= 0x48 && p <= 0x4F)
    return HX_INS_DEC;
  return HX_INS_OTHER;
}

/* Populate detail->regs_read/write for the curated set of RIP-capable
 * instructions that implicitly use GP registers, keeping the relocator
 * scratch-register selection (via hx_reg_read/write) safe. */
static void
note_implicit_regs (hx_insn * insn, uint8_t op1, uint8_t op0f, uint8_t modrm)
{
  hx_detail * d = insn->detail;
  int ext = (modrm >> 3) & 7;

  d->regs_read_count = 0;
  d->regs_write_count = 0;

  if (op0f == 0)
  {
    if (op1 == 0xF6 || op1 == 0xF7)
    {
      if (ext >= 4) /* MUL/IMUL/DIV/IDIV */
      {
        d->regs_read[d->regs_read_count++] = HX_REG_RAX;
        d->regs_write[d->regs_write_count++] = HX_REG_RAX;
        if (op1 == 0xF7)
        {
          d->regs_read[d->regs_read_count++] = HX_REG_RDX;
          d->regs_write[d->regs_write_count++] = HX_REG_RDX;
        }
      }
    }
    else if (op1 == 0xD2 || op1 == 0xD3) /* shift by CL */
    {
      d->regs_read[d->regs_read_count++] = HX_REG_RCX;
    }
  }
  else
  {
    if (op0f == 0xB0 || op0f == 0xB1) /* CMPXCHG */
    {
      d->regs_read[d->regs_read_count++] = HX_REG_RAX;
      d->regs_write[d->regs_write_count++] = HX_REG_RAX;
    }
    else if (op0f == 0xC7) /* CMPXCHG8B/16B */
    {
      d->regs_read[d->regs_read_count++] = HX_REG_RAX;
      d->regs_read[d->regs_read_count++] = HX_REG_RDX;
      d->regs_write[d->regs_write_count++] = HX_REG_RAX;
      d->regs_write[d->regs_write_count++] = HX_REG_RDX;
    }
  }
}

/* ---- the decoder -------------------------------------------------------- */

static bool
hx_decode (bool mode64,
           const uint8_t * code,
           size_t avail,
           uint64_t address,
           hx_insn * insn)
{
  DecState st;
  hx_x86 * x86 = &insn->detail->x86;
  const uint8_t * insn_start = code;
  uint8_t op, op0f = 0;
  uint8_t oc;
  const uint8_t * map = oc1;
  int vex_map = 0;
  bool is_vex = false;

  memset (&st, 0, sizeof (st));
  st.mode64 = mode64;
  st.p = code;
  st.start = code;

  memset (x86, 0, sizeof (*x86));
  insn->id = HX_INS_OTHER;
  insn->address = address;
  insn->detail->regs_read_count = 0;
  insn->detail->regs_write_count = 0;

  if (avail == 0)
    return false;

  /* legacy prefixes + REX */
  for (;;)
  {
    op = *st.p;
    oc = oc1[op];

    if (oc == OC_P66) { st.opsize = true; st.p++; continue; }
    if (oc == OC_P67) { st.addrsize = true; st.p++; continue; }
    if (oc == OC_PF2) { st.repne = true; st.p++; continue; }
    if (oc == OC_PF3) { st.rep = true; st.p++; continue; }
    if (oc == OC_SEG) { st.seg = op; st.p++; continue; }
    if (oc == OC_PREFIX) { st.p++; continue; }
    if (oc == OC_REX && mode64)
    {
      st.has_rex = true;
      st.rex = op;
      st.p++;
      op = *st.p;
      oc = oc1[op];
      break;
    }
    break;
  }

  /* VEX / EVEX / XOP */
  if (oc == OC_VEX2 && (mode64 || (st.p[1] & 0xC0) == 0xC0))
  {
    is_vex = true; vex_map = 1;
    st.p += 2;
  }
  else if (oc == OC_VEX3 && (mode64 || (st.p[1] & 0xC0) == 0xC0))
  {
    is_vex = true;
    vex_map = st.p[1] & 0x1f;
    if (st.p[2] & 0x80) st.rex |= 0x8;
    st.p += 3;
  }
  else if (oc == OC_XOP && (st.p[1] & 0x1f) >= 8)
  {
    is_vex = true;
    vex_map = st.p[1] & 0x1f;
    st.p += 3;
  }
  else if (oc == OC_EVEX && (mode64 || (st.p[1] & 0xC0) == 0xC0))
  {
    is_vex = true;
    vex_map = st.p[1] & 0x07;
    if (st.p[2] & 0x80) st.rex |= 0x8;
    st.p += 4;
  }

  if (is_vex)
  {
    uint8_t vop = *st.p;
    st.p++;
    decode_modrm (&st, insn, x86, insn_start);
    if (vex_map == 3 || vex_map == 10 ||
        (vex_map == 1 && (vop == 0x70 || vop == 0x71 || vop == 0x72 ||
            vop == 0x73 || vop == 0xC2 || vop == 0xC4 || vop == 0xC5 ||
            vop == 0xC6)))
    {
      skip_imm (&st, 1);
    }
    goto done;
  }

  /* opcode escape */
  if (oc == OC_ESC0F)
  {
    st.p++;
    op0f = *st.p;
    op = op0f;
    oc = oc0f[op0f];

    if (oc == OC_ESC38)
    {
      st.p++;
      st.p++;
      decode_modrm (&st, insn, x86, insn_start);
      map = oc0f;
      goto done;
    }
    if (oc == OC_ESC3A)
    {
      st.p++;
      st.p++;
      decode_modrm (&st, insn, x86, insn_start);
      skip_imm (&st, 1);
      map = oc0f;
      goto done;
    }

    st.p++;
    map = oc0f;
  }
  else
  {
    st.p++;
    map = oc1;
  }

  /* dispatch on op-class */
  switch (oc)
  {
    case OC_L1:
    case OC_L1_DYN:
      break;
    case OC_IB:
    case OC_IB_DYN:
      skip_imm (&st, 1);
      break;
    case OC_IW:
    case OC_IW_EOI:
      skip_imm (&st, 2);
      break;
    case OC_ENTER:
      skip_imm (&st, 3);
      break;
    case OC_IZ:
      skip_imm (&st, imm_z_size (&st));
      break;
    case OC_MOFFS:
      skip_imm (&st, st.mode64 ? (st.addrsize ? 4 : 8) : (st.addrsize ? 2 : 4));
      break;
    case OC_MOVIMM:
      if (st.rex & 0x8)
        skip_imm (&st, 8);
      else
        skip_imm (&st, imm_z_size (&st));
      break;
    case OC_M:
      decode_modrm (&st, insn, x86, insn_start);
      break;
    case OC_M_IB:
      decode_modrm (&st, insn, x86, insn_start);
      skip_imm (&st, 1);
      break;
    case OC_M_IZ:
    case OC_GRP_C7:
      decode_modrm (&st, insn, x86, insn_start);
      skip_imm (&st, imm_z_size (&st));
      break;
    case OC_GRP_F6:
      decode_modrm (&st, insn, x86, insn_start);
      if (((x86->modrm >> 3) & 6) == 0)
        skip_imm (&st, 1);
      break;
    case OC_GRP_F7:
      decode_modrm (&st, insn, x86, insn_start);
      if (((x86->modrm >> 3) & 6) == 0)
        skip_imm (&st, imm_z_size (&st));
      break;
    case OC_GRP_FF:
      decode_modrm (&st, insn, x86, insn_start);
      break;
    case OC_JCC8:
    case OC_LOOP8:
    {
      int8_t rel = (int8_t) st.p[0];
      st.p += 1;
      set_imm_target (x86, (int64_t) (address + (uint64_t) (st.p - insn_start) + (int64_t) rel));
      break;
    }
    case OC_REL_Z:
    {
      int zsz = imm_z_size (&st);
      int32_t rel;
      if (zsz == 2)
        rel = (int16_t) ((uint16_t) st.p[0] | ((uint16_t) st.p[1] << 8));
      else
        rel = (int32_t) ((uint32_t) st.p[0] | ((uint32_t) st.p[1] << 8) |
            ((uint32_t) st.p[2] << 16) | ((uint32_t) st.p[3] << 24));
      st.p += zsz;
      set_imm_target (x86, (int64_t) (address + (uint64_t) (st.p - insn_start) + (int64_t) rel));
      break;
    }
    case OC_FARPTR:
      if (st.mode64) { insn->size = 1; return false; }
      skip_imm (&st, st.opsize ? 4 : 6);
      break;
    case OC_INVALID:
    default:
      insn->size = 1;
      return false;
  }

done:
  insn->size = (uint16_t) (st.p - insn_start);
  if ((size_t) insn->size > avail)
  {
    insn->size = 1;
    return false;
  }

  memcpy (insn->bytes, insn_start, insn->size);
  x86->prefix[0] = st.seg;

  /* classify id */
  {
    uint8_t primary = op;
    bool two_byte = (map == oc0f);

    if (!is_vex && !two_byte)
    {
      if (primary == 0xE8) insn->id = HX_INS_CALL;
      else if (primary == 0xE9 || primary == 0xEB) insn->id = HX_INS_JMP;
      else if (primary >= 0x70 && primary <= 0x7F)
        insn->id = jcc_map[primary - 0x70];
      else if (primary == 0xE3)
        insn->id = st.mode64
            ? (st.addrsize ? HX_INS_JECXZ : HX_INS_JRCXZ)
            : (st.addrsize ? HX_INS_JCXZ : HX_INS_JECXZ);
      else if (primary == 0xE0) insn->id = HX_INS_LOOPNE;
      else if (primary == 0xE1) insn->id = HX_INS_LOOPE;
      else if (primary == 0xE2) insn->id = HX_INS_LOOP;
      else if (primary == 0xC2 || primary == 0xC3) insn->id = HX_INS_RET;
      else if (primary == 0xCA || primary == 0xCB) insn->id = HX_INS_RETF;
      else if (primary == 0xCC) insn->id = HX_INS_INT3;
      else if (primary == 0xCD || primary == 0xF1) insn->id = HX_INS_INT;
      else if (primary == 0x90 && !st.rep) insn->id = HX_INS_NOP;
      else if (primary >= 0x50 && primary <= 0x57) insn->id = HX_INS_PUSH;
      else if (primary == 0x68 || primary == 0x6A) insn->id = HX_INS_PUSH;
      else if (primary == 0xFF)
      {
        int ext = (x86->modrm >> 3) & 7;
        if (ext == 2 || ext == 3) insn->id = HX_INS_CALL;
        else if (ext == 4 || ext == 5) insn->id = HX_INS_JMP;
        else if (ext == 6) insn->id = HX_INS_PUSH;
        else if (ext == 0) insn->id = HX_INS_INC;
        else if (ext == 1) insn->id = HX_INS_DEC;
      }

      if (insn->id == HX_INS_OTHER)
        insn->id = classify_dp_1byte (primary, x86->modrm, st.mode64);
    }
    else if (!is_vex && two_byte)
    {
      if (primary >= 0x80 && primary <= 0x8F)
        insn->id = jcc_map[primary - 0x80];   /* near Jcc (0F 8x rel32) */
      else if (primary == 0x05) insn->id = HX_INS_SYSCALL;
      else if (primary == 0x34) insn->id = HX_INS_SYSENTER;
      else if (primary == 0x1F) insn->id = HX_INS_NOP;
      else if (primary == 0xB0 || primary == 0xB1) insn->id = HX_INS_CMPXCHG;
    }

    if (!is_vex)
      note_implicit_regs (insn, two_byte ? 0 : primary, two_byte ? primary : 0,
          x86->modrm);
  }

  return true;
}

/* ---- capstone shim API -------------------------------------------------- */

typedef struct
{
  bool mode64;
  bool detail;
} HxHandle;

hx_err
hx_open (hx_arch arch, hx_mode mode, hx_csh * handle)
{
  HxHandle * h;

  if (arch != HX_ARCH_X86)
    return HX_ERR_ARCH;

  h = calloc (1, sizeof (HxHandle));
  if (h == NULL)
    return HX_ERR_MEM;

  h->mode64 = (mode & HX_MODE_64) != 0;
  h->detail = false;
  *handle = (hx_csh) (size_t) h;

  return HX_ERR_OK;
}

hx_err
hx_close (hx_csh * handle)
{
  if (handle == NULL || *handle == 0)
    return HX_ERR_HANDLE;
  free ((void *) (size_t) *handle);
  *handle = 0;
  return HX_ERR_OK;
}

hx_err
hx_option (hx_csh handle, hx_opt_type type, size_t value)
{
  HxHandle * h = (HxHandle *) (size_t) handle;

  if (type == HX_OPT_DETAIL)
    h->detail = (value == HX_OPT_ON);
  else if (type == HX_OPT_MODE)
    h->mode64 = (value & HX_MODE_64) != 0;

  return HX_ERR_OK;
}

hx_insn *
hx_insn_alloc (hx_csh handle)
{
  hx_insn * insn = calloc (1, sizeof (hx_insn));
  (void) handle;
  if (insn == NULL)
    return NULL;
  insn->detail = calloc (1, sizeof (hx_detail));
  if (insn->detail == NULL)
  {
    free (insn);
    return NULL;
  }
  return insn;
}

void
hx_insn_free (hx_insn * insn, size_t count)
{
  size_t i;
  for (i = 0; i < count; i++)
    free (insn[i].detail);
  free (insn);
}

bool
hx_disasm_iter (hx_csh handle, const uint8_t ** code, size_t * size,
    uint64_t * address, hx_insn * insn)
{
  HxHandle * h = (HxHandle *) (size_t) handle;

  if (*size == 0)
    return false;

  if (!hx_decode (h->mode64, *code, *size, *address, insn))
    return false;

  *code += insn->size;
  *size -= insn->size;
  *address += insn->size;

  return true;
}

size_t
hx_disasm (hx_csh handle, const uint8_t * code, size_t code_size,
    uint64_t address, size_t count, hx_insn ** insn)
{
  HxHandle * h = (HxHandle *) (size_t) handle;
  size_t cap = (count != 0) ? count : 64;
  size_t n = 0;
  hx_insn * arr = calloc (cap, sizeof (hx_insn));
  const uint8_t * p = code;
  size_t remaining = code_size;
  uint64_t addr = address;

  if (arr == NULL)
    return 0;

  while (remaining > 0 && (count == 0 || n < count))
  {
    hx_detail * detail = calloc (1, sizeof (hx_detail));
    arr[n].detail = detail;
    if (!hx_decode (h->mode64, p, remaining, addr, &arr[n]))
    {
      free (detail);
      arr[n].detail = NULL;
      break;
    }
    p += arr[n].size;
    remaining -= arr[n].size;
    addr += arr[n].size;
    n++;
    if (n == cap && count == 0)
    {
      hx_insn * grown;

      cap *= 2;
      grown = realloc (arr, cap * sizeof (hx_insn));
      if (grown == NULL)
        break;
      arr = grown;
    }
  }

  *insn = arr;
  return n;
}

static bool
reg_in (const uint16_t * arr, uint8_t n, unsigned int reg)
{
  uint8_t i;
  for (i = 0; i < n; i++)
    if (arr[i] == reg)
      return true;
  return false;
}

bool
hx_reg_read (hx_csh handle, const hx_insn * insn, unsigned int reg_id)
{
  (void) handle;
  return reg_in (insn->detail->regs_read, insn->detail->regs_read_count,
      (uint16_t) reg_id);
}

bool
hx_reg_write (hx_csh handle, const hx_insn * insn, unsigned int reg_id)
{
  (void) handle;
  return reg_in (insn->detail->regs_write, insn->detail->regs_write_count,
      (uint16_t) reg_id);
}

void
hx_arch_register_x86 (void)
{
}
