#define HOOX_ARM64_ADRP_MAX_DISTANCE 0xfffff000
#define HOOX_ARM64_B_MAX_DISTANCE 0x07fffffc

#define HOOX_ARM64_SYSREG(op0, op1, crn, crm, op2) \
    ( \
      (((op0 == 2) ? 0 : 1) << 14) | \
      (op1 << 11) | \
      (crn << 7) | \
      (crm << 3) | \
      op2 \
    )
#define HOOX_ARM64_SYSREG_TPIDRRO_EL0 HOOX_ARM64_SYSREG (3, 3, 13, 0, 3)

