static hx_boolean
hoox_arm64_writer_put_blr_reg_with_extra (HooxArm64Writer * self,
                                         hx_arm64_reg reg,
                                         hx_uint32 extra)
{
  HooxArm64RegInfo ri;

  hoox_arm64_writer_describe_reg (self, reg, &ri);

  if (ri.width != 64)
    return FALSE;

  hoox_arm64_writer_put_instruction (self, 0xd63f0000 | (ri.index << 5) | extra);

  return TRUE;
}

