#define HOOX_IS_WITHIN_INT20_RANGE(i) \
    (((hx_int64) (i)) >= HX_INT64_CONSTANT (-524288) && \
     ((hx_int64) (i)) <= HX_INT64_CONSTANT (524287))
#define HOOX_IS_WITHIN_INT21_RANGE(i) \
