/* ---- operands ----------------------------------------------------------- */

typedef enum hx_x86_op_type
{
  HX_OP_INVALID = 0,
  HX_OP_REG,
  HX_OP_IMM,
  HX_OP_MEM,
} hx_x86_op_type;

typedef struct hx_x86_op_mem
{
  hx_x86_reg segment;
  hx_x86_reg base;
  hx_x86_reg index;
  int scale;
  int64_t disp;
} hx_x86_op_mem;

typedef struct hx_x86_op
{
  hx_x86_op_type type;
  union
  {
    hx_x86_reg reg;
    int64_t imm;
    hx_x86_op_mem mem;
  };
  uint8_t size;
} hx_x86_op;

typedef struct hx_x86_encoding
{
  uint8_t modrm_offset;
  uint8_t disp_offset;
  uint8_t disp_size;
  uint8_t imm_offset;
  uint8_t imm_size;
} hx_x86_encoding;

#define HX_HX_MAX_OPS 4

typedef struct hx_x86
{
  uint8_t prefix[4];
  uint8_t opcode[4];
  uint8_t rex;
  uint8_t addr_size;
  uint8_t modrm;
  uint8_t sib;
  int64_t disp;
  hx_x86_encoding encoding;

  uint8_t op_count;
  hx_x86_op operands[HX_HX_MAX_OPS];
} hx_x86;

