/* Bounded string copy. MSVC deprecates strncpy (C4996), so route to the
 * bounds-checked strncpy_s there; every other toolchain uses plain strncpy.
 * `dst` must hold `dst_size` bytes; at most `count` chars are copied. */
#include <string.h>
#if defined (_MSC_VER)
# define hx_strncpy(dst, dst_size, src, count) \
    strncpy_s ((dst), (dst_size), (src), (count))
#else
# define hx_strncpy(dst, dst_size, src, count) \
    strncpy ((dst), (src), (count))
#endif

#define HX_STRINGIFY(macro_or_string) HX_STRINGIFY_ARG (macro_or_string)
#define HX_STRINGIFY_ARG(contents) #contents

#define HX_PASTE(identifier1, identifier2) \
    HX_PASTE_ARGS (identifier1, identifier2)
#define HX_PASTE_ARGS(identifier1, identifier2) identifier1 ## identifier2

/* hx_steal_pointer / hx_clear_pointer live with the memory helpers but the
 * inline forms are handy from headers, so declare them here. */
static inline hx_pointer
hx_steal_pointer (hx_pointer pp)
{
  hx_pointer * ptr = (hx_pointer *) pp;
  hx_pointer ref = *ptr;
  *ptr = NULL;
  return ref;
}

