struct _HooxIA32CpuContext
{
  hx_uint32 eip;

  hx_uint32 edi;
  hx_uint32 esi;
  hx_uint32 ebp;
  hx_uint32 esp;
  hx_uint32 ebx;
  hx_uint32 edx;
  hx_uint32 ecx;
  hx_uint32 eax;
};

struct _HooxX64CpuContext
{
  hx_uint64 rip;

  hx_uint64 r15;
  hx_uint64 r14;
  hx_uint64 r13;
  hx_uint64 r12;
  hx_uint64 r11;
  hx_uint64 r10;
  hx_uint64 r9;
  hx_uint64 r8;

  hx_uint64 rdi;
  hx_uint64 rsi;
  hx_uint64 rbp;
  hx_uint64 rsp;
  hx_uint64 rbx;
  hx_uint64 rdx;
  hx_uint64 rcx;
  hx_uint64 rax;
};

union _HooxArmVectorReg
{
  hx_uint8 q[16];
  hx_double d[2];
  hx_float s[4];
};

struct _HooxArmCpuContext
{
  hx_uint32 pc;
  hx_uint32 sp;
  hx_uint32 cpsr;

  hx_uint32 r8;
  hx_uint32 r9;
  hx_uint32 r10;
  hx_uint32 r11;
  hx_uint32 r12;

  HooxArmVectorReg v[16];

  hx_uint32 _padding;

  hx_uint32 r[8];
  hx_uint32 lr;
};

union _HooxArm64VectorReg
{
  hx_uint8 q[16];
  hx_double d;
  hx_float s;
  hx_uint16 h;
  hx_uint8 b;
};

struct _HooxArm64CpuContext
{
  hx_uint64 pc;
  hx_uint64 sp;
  hx_uint64 nzcv;

  hx_uint64 x[29];
  hx_uint64 fp;
  hx_uint64 lr;

#ifndef HX_OS_NONE
  /* Bare-metal threads can be entered with a near-exhausted kernel stack, so
   * there the trampolines stay integer-only and skip the vector registers. */
  HooxArm64VectorReg v[32];
#endif
};

enum _HooxRelocationScenario
{
  HOOX_SCENARIO_OFFLINE,
  HOOX_SCENARIO_ONLINE
};

