#define HOOX_ALIGN_POINTER(t, p, b) \
    ((t) HX_SIZE_TO_POINTER (((HX_POINTER_TO_SIZE (p) + ((hx_size) (b - 1))) & \
        ~((hx_size) (b - 1)))))
#define HOOX_ALIGN_SIZE(s, b) \
    ((((hx_size) s) + ((hx_size) (b - 1))) & ~((hx_size) (b - 1)))

