#ifndef MAX
# define MAX(a, b) (((a) > (b)) ? (a) : (b))
#endif
#ifndef ABS
# define ABS(a) (((a) < 0) ? -(a) : (a))
#endif
#ifndef CLAMP
# define CLAMP(x, low, high) (((x) > (high)) ? (high) : (((x) < (low)) ? (low) : (x)))
#endif

#define HX_POINTER_TO_INT(p)   ((hx_int) (hx_intptr) (p))
#define HX_POINTER_TO_UINT(p)  ((hx_uint) (hx_uintptr) (p))
