/* ---- target detection ---------------------------------------------------
 * Prefer an explicit HAVE_<arch> / HAVE_<os> from the build system; otherwise
 * derive it from the compiler's built-in macros so the amalgamated library
 * needs no -D flags on common targets. Define the macro yourself only if
 * auto-detection cannot classify your target. */
#if !defined (HAVE_I386) && !defined (HAVE_ARM) && !defined (HAVE_ARM64)
# if defined (_M_IX86) || defined (__i386__) || \
     defined (_M_X64) || defined (__x86_64__)
#  define HAVE_I386
# elif defined (_M_ARM64) || defined (__aarch64__)
#  define HAVE_ARM64
# elif defined (_M_ARM) || defined (__arm__)
#  define HAVE_ARM
# endif
#endif

#if !defined (HAVE_WINDOWS) && !defined (HAVE_DARWIN) && \
    !defined (HAVE_LINUX) && !defined (HAVE_FREEBSD)
# if defined (_WIN32)
#  define HAVE_WINDOWS
# elif defined (__APPLE__)
#  define HAVE_DARWIN
# elif defined (__linux__)
#  define HAVE_LINUX
# elif defined (__FreeBSD__)
#  define HAVE_FREEBSD
# endif
#endif

/* Android is a Linux kernel with bionic libc: it reuses the Linux backend and
 * additionally defines HAVE_ANDROID for the few Android-specific quirks (e.g.
 * execute-only code pages on API 29+). */
#if defined (__ANDROID__) && !defined (HAVE_ANDROID)
# define HAVE_ANDROID
#endif

/* iOS / tvOS share the Darwin backend with macOS; distinguish them for the few
 * Apple-mobile-specific paths (code segment, ptrauth target-OS). Both the
 * device and the simulator define TARGET_OS_IOS. */
#if defined (__APPLE__)
# include <TargetConditionals.h>
# if defined (TARGET_OS_IOS) && TARGET_OS_IOS && !defined (HAVE_IOS)
#  define HAVE_IOS
# endif
# if defined (TARGET_OS_TV) && TARGET_OS_TV && !defined (HAVE_TVOS)
#  define HAVE_TVOS
# endif
#endif

/* arm64e uses authenticated code pointers. Apple Clang exposes this through
 * either the target macro or the ptrauth_calls feature; detect it here so both
 * normal and amalgamated builds select the signing paths automatically. */
#if defined (__APPLE__) && defined (HAVE_ARM64) && !defined (HAVE_PTRAUTH)
# if defined (__arm64e__)
#  define HAVE_PTRAUTH
# elif defined (__has_feature)
#  if __has_feature (ptrauth_calls)
#   define HAVE_PTRAUTH
#  endif
# endif
#endif

#if HX_API_MAJOR >= 6
# define HX_ARCH_ARM64 HX_ARCH_AARCH64
#endif

/* Static linkage is the default. Define HOOX_SHARED to build/consume hoox as
 * a Windows DLL (and HOOX_EXPORTS while building that DLL). */
#if defined (HOOX_SHARED) && defined (HX_OS_WIN32)
#  ifdef HOOX_EXPORTS
#    define HOOX_API __declspec (dllexport)
#  else
#    define HOOX_API __declspec (dllimport)
#  endif
#else
#  define HOOX_API
#endif

