{
  hx_uint32 pc;
  hx_uint32 sp;
  hx_uint32 cpsr;

  hx_uint32 r8;
  hx_uint32 r9;
  hx_uint32 r10;
  hx_uint32 r11;
  hx_uint32 r12;

  HooxArmVectorReg v[16];

  hx_uint32 _padding;

  hx_uint32 r[8];
  hx_uint32 lr;
};

union _HooxArm64VectorReg
{
  hx_uint8 q[16];
  hx_double d;
  hx_float s;
  hx_uint16 h;
  hx_uint8 b;
};

struct _HooxArm64CpuContext
{
  hx_uint64 pc;
  hx_uint64 sp;
  hx_uint64 nzcv;

  hx_uint64 x[29];
  hx_uint64 fp;
  hx_uint64 lr;

#ifndef HX_OS_NONE
  /* Bare-metal threads can be entered with a near-exhausted kernel stack, so
   * there the trampolines stay integer-only and skip the vector registers. */
  HooxArm64VectorReg v[32];
#endif
};

