#include <string.h>
#include <unistd.h>
#include <sys/mman.h>

typedef struct _HooxFindRangeProtContext HooxFindRangeProtContext;

struct _HooxFindRangeProtContext
{
  HooxAddress address;

  hx_boolean found;
  HooxPageProtection protection;
};

static hx_boolean hoox_store_protection_if_containing_address (
    const HooxRangeDetails * details, hx_pointer user_data);

hx_boolean
hoox_memory_query_protection (hx_constpointer address,
                             HooxPageProtection * prot)
{
  HooxFindRangeProtContext ctx;

  ctx.address = HOOX_ADDRESS (address);
  ctx.found = FALSE;
  ctx.protection = HOOX_PAGE_NO_ACCESS;

  _hoox_process_enumerate_ranges (HOOX_PAGE_NO_ACCESS,
      hoox_store_protection_if_containing_address, &ctx);

  if (ctx.found)
    *prot = ctx.protection;

  return ctx.found;
}

static hx_boolean
hoox_store_protection_if_containing_address (const HooxRangeDetails * details,
                                            hx_pointer user_data)
{
  HooxFindRangeProtContext * ctx = user_data;
  hx_boolean proceed = TRUE;

  if (HOOX_MEMORY_RANGE_INCLUDES (details->range, ctx->address))
  {
    ctx->found = TRUE;
    ctx->protection = details->protection;

    proceed = FALSE;
  }

  return proceed;
}

hx_boolean
hoox_memory_can_remap_writable (void)
{
  return FALSE;
}

hx_pointer
hoox_memory_try_remap_writable_pages (hx_pointer first_page,
                                     hx_uint n_pages)
{
  (void) first_page;
  (void) n_pages;
  return NULL;
}

void
hoox_memory_dispose_writable_pages (hx_pointer first_page,
                                   hx_uint n_pages)
{
  (void) first_page;
  (void) n_pages;
}

hx_boolean
hoox_try_mprotect (hx_pointer address,
                  hx_size size,
                  HooxPageProtection prot)
{
  hx_size page_size;
  hx_pointer aligned_address;
  hx_size aligned_size;
  hx_int posix_prot;
  hx_int result;

  hx_assert (size != 0);

  page_size = hoox_query_page_size ();
  aligned_address = HX_SIZE_TO_POINTER (
      HX_POINTER_TO_SIZE (address) & ~(page_size - 1));
  aligned_size =
      (1 + (((hx_uint8 *) address + size - 1 - (hx_uint8 *) aligned_address) /
      page_size)) * page_size;
  posix_prot = _hoox_page_protection_to_posix (prot);

  result = mprotect (aligned_address, aligned_size, posix_prot);

  return result == 0;
}

void
hoox_clear_cache (hx_pointer address,
                 hx_size size)
{
#if defined (HAVE_ARM) || defined (HAVE_ARM64)
  __builtin___clear_cache ((char *) address, (char *) address + size);
#else
  (void) address;
  (void) size;
#endif
}
#endif /* defined (HAVE_FREEBSD) */

/* ==== source: hooxcpu-arm.c ==== */
#if defined (HAVE_ARM)
/*
 * hoox — ARM CPU feature query.
 *
 * The ARM writer/relocator/interceptor ask which VFP/interworking features are
 * available so the generated trampolines only use instructions the CPU has. On
 * Linux this is read from the ELF auxiliary vector (AT_HWCAP); ARMv7 always
 * supports Thumb interworking (BX), so that bit is set unconditionally.
 *
 * Licence: wxWindows Library Licence, Version 3.1
 */


#if defined (HAVE_LINUX) || defined (__linux__)
# include <sys/auxv.h>
# ifndef AT_HWCAP
#  define AT_HWCAP 16
# endif
# ifndef HWCAP_VFP
#  define HWCAP_VFP (1 << 6)
# endif
# ifndef HWCAP_VFPv3
#  define HWCAP_VFPv3 (1 << 13)
# endif
# ifndef HWCAP_VFPD32
#  define HWCAP_VFPD32 (1 << 19)
# endif
#endif

static HooxCpuFeatures hoox_do_query_cpu_features (void);

HooxCpuFeatures
hoox_query_cpu_features (void)
{
  static hx_size cached_result = 0;

  if (hx_once_init_enter (&cached_result))
  {
    HooxCpuFeatures features = hoox_do_query_cpu_features ();

    hx_once_init_leave (&cached_result, features + 1);
  }

  return (HooxCpuFeatures) (cached_result - 1);
}

static HooxCpuFeatures
hoox_do_query_cpu_features (void)
{
  HooxCpuFeatures features = HOOX_CPU_THUMB_INTERWORK;

#if defined (HAVE_LINUX) || defined (__linux__)
  unsigned long hwcap = getauxval (AT_HWCAP);

  if ((hwcap & HWCAP_VFP) != 0)
    features |= HOOX_CPU_VFP2;
  if ((hwcap & HWCAP_VFPv3) != 0)
    features |= HOOX_CPU_VFP3;
  if ((hwcap & HWCAP_VFPD32) != 0)
    features |= HOOX_CPU_VFPD32;
#else
  /* Conservative default for non-Linux ARM: assume a VFPv3-D32 core. */
  features |= HOOX_CPU_VFP2 | HOOX_CPU_VFP3 | HOOX_CPU_VFPD32;
#endif

  return features;
}
#endif /* defined (HAVE_ARM) */

/* ==== source: hooxcpucontext-arm.c ==== */
#if defined (HAVE_ARM)
/*
 * Copyright (C) 2010 Ole André Vadla Ravnås <oleavr@nowsecure.com>
 *
 * Licence: wxWindows Library Licence, Version 3.1
 */


hx_pointer
hoox_cpu_context_get_nth_argument (HooxCpuContext * self,
                                  hx_uint n)
{
  if (n < 4)
  {
    return (hx_pointer) self->r[n];
  }
  else
  {
    hx_pointer * stack_argument = (hx_pointer *) self->sp;

    return stack_argument[n - 4];
  }
}

void
hoox_cpu_context_replace_nth_argument (HooxCpuContext * self,
                                      hx_uint n,
                                      hx_pointer value)
{
  if (n < 4)
  {
    self->r[n] = (hx_uint32) value;
  }
  else
  {
    hx_pointer * stack_argument = (hx_pointer *) self->sp;

    stack_argument[n - 4] = value;
  }
}

hx_pointer
hoox_cpu_context_get_return_value (HooxCpuContext * self)
{
  return (hx_pointer) self->r[0];
}

void
hoox_cpu_context_replace_return_value (HooxCpuContext * self,
                                      hx_pointer value)
{
  self->r[0] = (hx_uint32) value;
}
#endif /* defined (HAVE_ARM) */

