#ifdef _MSC_VER
# include <intrin.h>
#else
# include <cpuid.h>
#endif

static HooxCpuFeatures hoox_do_query_cpu_features (void);
static hx_boolean hoox_get_cpuid (hx_uint level, hx_uint * a, hx_uint * b, hx_uint * c,
    hx_uint * d);

HooxCpuFeatures
hoox_query_cpu_features (void)
{
  static hx_size cached_result = 0;

  if (hx_once_init_enter (&cached_result))
  {
    HooxCpuFeatures features = hoox_do_query_cpu_features ();

    hx_once_init_leave (&cached_result, features + 1);
  }

  return (HooxCpuFeatures) (cached_result - 1);
}

static HooxCpuFeatures
hoox_do_query_cpu_features (void)
{
  HooxCpuFeatures features = 0;
  hx_boolean cpu_supports_avx2 = FALSE;
  hx_boolean cpu_supports_cet_ss = FALSE;
  hx_boolean os_enabled_xsave = FALSE;
  hx_uint a, b, c, d;

  if (hoox_get_cpuid (7, &a, &b, &c, &d))
  {
    cpu_supports_avx2 = (b & (1 << 5)) != 0;
    cpu_supports_cet_ss = (c & (1 << 7)) != 0;
  }

  if (hoox_get_cpuid (1, &a, &b, &c, &d))
    os_enabled_xsave = (c & (1 << 27)) != 0;

  if (cpu_supports_avx2 && os_enabled_xsave)
    features |= HOOX_CPU_AVX2;

  if (cpu_supports_cet_ss)
    features |= HOOX_CPU_CET_SS;

  return features;
}

static hx_boolean
hoox_get_cpuid (hx_uint level,
               hx_uint * a,
               hx_uint * b,
               hx_uint * c,
               hx_uint * d)
{
#ifdef _MSC_VER
  hx_int info[4];
  hx_uint n;

  __cpuid (info, 0);
  n = info[0];
  if (n < level)
    return FALSE;

  __cpuid (info, level);

  *a = info[0];
  *b = info[1];
  *c = info[2];
  *d = info[3];

  return TRUE;
#else
  hx_uint n;

  n = __get_cpuid_max (0, NULL);
  if (n < level)
    return FALSE;

  __cpuid_count (level, 0, *a, *b, *c, *d);

  return TRUE;
#endif
}

#endif /* defined (HAVE_I386) */

/* ==== source: hooxcpucontext-x86.c ==== */
#if defined (HAVE_I386)
/*
 * Copyright (C) 2008-2017 Ole André Vadla Ravnås <oleavr@nowsecure.com>
 *
 * Licence: wxWindows Library Licence, Version 3.1
 */


hx_pointer
hoox_cpu_context_get_nth_argument (HooxCpuContext * self,
                                  hx_uint n)
{
  hx_pointer * stack_argument;

#if HX_SIZEOF_VOID_P == 4
  stack_argument = (hx_pointer *) (self->esp + 4);
  return stack_argument[n];
#else
  stack_argument = (hx_pointer *) (self->rsp + 8);
  switch (n)
  {
# if HOOX_NATIVE_ABI_IS_UNIX
    case 0:  return (hx_pointer) self->rdi;
    case 1:  return (hx_pointer) self->rsi;
    case 2:  return (hx_pointer) self->rdx;
    case 3:  return (hx_pointer) self->rcx;
    case 4:  return (hx_pointer) self->r8;
    case 5:  return (hx_pointer) self->r9;
    default: return            stack_argument[n - 6];
# else
    case 0:  return (hx_pointer) self->rcx;
    case 1:  return (hx_pointer) self->rdx;
    case 2:  return (hx_pointer) self->r8;
    case 3:  return (hx_pointer) self->r9;
    default: return            stack_argument[n];
# endif
  }
#endif
}

void
hoox_cpu_context_replace_nth_argument (HooxCpuContext * self,
                                      hx_uint n,
                                      hx_pointer value)
{
  hx_pointer * stack_argument;

#if HX_SIZEOF_VOID_P == 4
  stack_argument = (hx_pointer *) (self->esp + 4);
  stack_argument[n] = value;
#else
  stack_argument = (hx_pointer *) (self->rsp + 8);
  switch (n)
  {
# if HOOX_NATIVE_ABI_IS_UNIX
    case 0:  self->rdi             = (hx_uint64) value; break;
    case 1:  self->rsi             = (hx_uint64) value; break;
    case 2:  self->rdx             = (hx_uint64) value; break;
    case 3:  self->rcx             = (hx_uint64) value; break;
    case 4:  self->r8              = (hx_uint64) value; break;
    case 5:  self->r9              = (hx_uint64) value; break;
    default: stack_argument[n - 6] =           value; break;
# else
    case 0:  self->rcx             = (hx_uint64) value; break;
    case 1:  self->rdx             = (hx_uint64) value; break;
    case 2:  self->r8              = (hx_uint64) value; break;
    case 3:  self->r9              = (hx_uint64) value; break;
    default: stack_argument[n]     =           value; break;
# endif
  }
#endif
}

hx_pointer
hoox_cpu_context_get_return_value (HooxCpuContext * self)
{
#if HX_SIZEOF_VOID_P == 4
  return (hx_pointer) self->eax;
#else
  return (hx_pointer) self->rax;
#endif
}

void
hoox_cpu_context_replace_return_value (HooxCpuContext * self,
                                      hx_pointer value)
{
#if HX_SIZEOF_VOID_P == 4
  self->eax = (hx_uint32) value;
#else
  self->rax = (hx_uint64) value;
#endif
}
#endif /* defined (HAVE_I386) */

